849	    enqueueScopedMutation(rootPaths, operation, allowConflict = false) {
850	        const execute = async () => {
851	            if (this.refreshPromise) await this.refreshPromise;
852	            this.stopTimer();
853	            if (!this.project) throw new Error('Worktree service has no active project');
854	            if (!allowConflict) this.mergeConflictService?.assertMutationAllowed(this.project.rootPath);
855	            const activeProject = this.project;
856	            let mutationRoots = rootPaths;
857	            if (mutationRoots === null) {
858	                const records = await this.readWorktreeRecords(activeProject);
859	                if (this.project !== activeProject) throw new Error('Opened project changed before worktree operation');
860	                this.records = records;
861	                this.publish(null);
862	                mutationRoots = [
863	                    this.project.rootPath,
864	                    ...this.records.filter(({ valid }) => valid).map(({ path: recordPath }) => recordPath),
865	                ];
866	            }
867	
868	            return withGitIndexMutations(mutationRoots, operation);
