59	function createFailedCleanGitRunner(cleanError, statusOutput) {
60	    let cleanFailed = false;
61	
62	    return vi.fn(async (rootPath, argumentsValue) => {
63	        if (argumentsValue[0] === 'clean' && argumentsValue[1] === '-fd') {
64	            cleanFailed = true;
65	            throw cleanError;
66	        }
67	        if (cleanFailed && argumentsValue[0] === 'status' && argumentsValue[1] === '--porcelain') return statusOutput;
68	
69	        return runGit(rootPath, argumentsValue);
70	    });
71	}
